from sys import stdin

def solve():
    N = int(stdin.readline())
    seq = list(map(int, stdin.readline().split()))

    while len(seq) > 1:
        max_val = -float('inf')
        max_idx = -1
        for i in range(len(seq)):
            if i == 0 or i == len(seq) - 1:
                val = seq[i]
            else:
                val = seq[i] + seq[i-1] + seq[i+1]
            if val > max_val:
                max_val = val
                max_idx = i

        if max_idx == 0:
            seq.pop(0)
        elif max_idx == len(seq) - 1:
            seq.pop()
        else:
            seq[max_idx] += seq[max_idx-1] + seq[max_idx+1]
            seq.pop(max_idx-1)
            seq.pop(max_idx)

        yield max_idx + 1

    yield seq[0]

if __name__ == "__main__":
    for result in solve():
        print(result)
